import numpy as np
from scipy.optimize import least_squares
x=eps; t=T
def model(p, kind):
    a,b,c,d,k,q,h,i,g,e = p
    with np.errstate(all='ignore'):
        if kind==0: rate = np.clip(k*x/t**q,-50,50)
        if kind==1: rate = np.clip(k*x*np.exp(np.clip(q/t,-50,50)),-50,50)
        if kind==2: rate = np.clip(k*x*t**q,-50,50)
    sat = (c + d*t + g*t*t)*(1-np.exp(-rate))
    return a + b*t + sat + (h+i*t)*x + e*x*x
